@unique
class SCRadioTypes(Enum):
    ASIR_HUB = "ASIR-HUB"


class RU(object):
    """RU attached to the testline.

    hw_group should define family of types that are mostly interchangeable from the
    verification point of view.
    """

    def __init__(
        self,
        ru_hw_group: str,
        default_ssh_connection_details: Optional["SshServiceDetails"] = None,
        lmp_connection: Optional["SshServiceDetails"] = None,
        pdu_port: Optional[PduPort] = None,
        pdu_ports: Optional[list[PduPort]] = None,
        radio_type: Optional[str] = None,
        signal_analyzer: Optional["SignalAnalyzer"] = None,
        attenuation_ports: Optional[List["AttenuationPort"]] = None,
        optical_switch_channels: Optional[List["SwitchChannel"]] = None,
        default_telnet_connection_details: Optional["TelnetConnectionDetails"] = None,
        serial_number: Optional[str] = None,
        alds: Optional[List["ALD"]] = None,
        channel_emulator_ports: Optional[List["ChannelEmulatorPort"]] = None,
        ru_extensions: Optional[List["RUExtension"]] = None,
        product_code: Optional[str] = None,
        mcs_ports: Optional[List["MCSPort"]] = None,
        positioner: Optional["RadioHeadPositioner"] = None,
        mac_address: Optional[str] = None,
        lmi: Optional["DiagnosticCard"] = None,
        fhm: Optional[bool] = None,
        rf_switch_ports: Optional[List["RFSwitchPort"]] = None,
    ):
        """

        :param str ru_hw_group: Radio Unit hardware group
        :param Optional[SshServiceDetails] default_ssh_connection_details: SshServiceDetails class instance object
        :param Optional[SshServiceDetails] lmp_connection: SshServiceDetails class instance object
        :param PduPort pdu_port: PduPort class instance object, mandatory parameter
        :param Optional[list[PduPort]] pdu_ports: List of PDU ports providing power to radio
        :param Optional[str] radio_type: str type (unique identifier) of the radio module, should be one of RadioTypes' attributes
        :param Optional[SignalAnalyzer] signal_analyzer: configuration object of signal analyzer connected to RU
        :param Optional[List[AttenuationPort]] attenuation_ports: attenuation ports connected to RU
        :param Optional[List[SwitchChannel]] optical_switch_channels: optical switch channels connected to RU
        :param Optional[TelnetConnectionDetails] default_telnet_connection_details: TelnetConnectionDetails class instance object
        :param Optional[str] serial_number: serial number of RU
        :param Optional[List[ALD]] alds: a list of sequentially connected Antenna Line Device
        :param Optional[List[ChannelEmulatorPort]] channel_emulator_ports: channel emulator ports connected to RU
        :param Optional[List[RUExtension]] ru_extensions: a list of connected Radio Unit Extensions
        :param Optional[str] product_code: product code of RU
        :param Optional[List[MCSPort]] mcs_ports: mcs ports connected to RU
        :param Optional[RadioHeadPositioner] positioner: RadioHeadPositioner reference or None if no positioner/actuator used
        :param Optional[str] mac_address: mac address, it's introduced for DC (direct connect) support
        :param Optional[DiagnosticCard] lmi: DiagnosticCard instance representing LMI card in the RU
        :param Optional[bool] fhm: None if FHM (Fronthaul Multiplexer) is not connected else True
        :param Optional[List[RFSwitchPort]] rf_switch_ports: RF switch ports connected to RU
        """
        # TODO: change radio_type parameter to enum (discuss whether it's the best solution fisrt)
        # TODO: change order of paramteres, so that pdu_port will be mandatory

        self.ru_hw_group = ru_hw_group
        self.default_ssh_connection_details = default_ssh_connection_details
        self.lmp_connection = lmp_connection
        self.pdu_port = pdu_port
        self.pdu_ports = pdu_ports or [pdu_port]
        self.radio_type = radio_type
        self.signal_analyzer = signal_analyzer
        self.attenuation_ports = attenuation_ports
        self.optical_switch_channels = optical_switch_channels
        self.default_telnet_connection_details = default_telnet_connection_details
        self.serial_number = serial_number
        self.alds = alds
        self.channel_emulator_ports = channel_emulator_ports
        self.ru_extensions = ru_extensions
        self.product_code = product_code
        self.mcs_ports = mcs_ports
        self.positioner = positioner
        self.mac_address = mac_address
        self.lmi = lmi
        self.fhm = fhm
        self.rf_switch_ports = rf_switch_ports

    def __taf_contract_radioheadpositioner__(self):
        if self.positioner is None:
            raise ValueError(
                f"RadioHeadPositioner information is not set in this configuration "
                f"object ({self.__class__!r})"
            )
        return self.positioner.__taf_contract_radioheadpositioner__()


class NonNokiaRU(RU):
    """NonNokiaRUs - used in ORAN use cases"""

    def __init__(self, *args, **kwargs):
        super().__init__(ru_hw_group="ThirdParty", *args, **kwargs)


@unique
class SamjiRadioTypes(Enum):
    OSQA = "OSQA"


class SamjiRU(NonNokiaRU):
    """NonNokiaRUs - common class for all RUS from Samji used in ORAN use cases. 'ru_hw_group' of 'RU' object will be
    automatically assigned a hardcoded value of "ThirdParty". The order of attributes is purposely different from that of a parent class.

    :param str radio_type: str type (unique identifier) of the radio module, should be one of 'SamjiRadioTypes' attributes
    :param Optional[SshServiceDetails] netconf_ssh_connection_details: SshServiceDetails class instance object for netconf configuration
    :param Optional[str] hw_version: detailed hardware version/iteration of the specific radio type
    :param Optional[str] serial_number: serial number of RU
    :param Optional[str] product_code: product code of RU
    :param Optional[PduPort] pdu_port: PduPort class instance object, mandatory parameter
    :param Optional[RadioHeadPositioner] positioner: RadioHeadPositioner reference or None if no positioner/actuator used
    """

    def __init__(
        self,
        radio_type,
        netconf_ssh_configuration=None,
        hw_version=None,
        serial_number=None,
        product_code=None,
        pdu_port=None,
        positioner=None,
    ):
        super().__init__(
            radio_type=radio_type,
            serial_number=serial_number,
            product_code=product_code,
            pdu_port=pdu_port,
            positioner=positioner,
        )
        self.netconf_ssh_configuration = netconf_ssh_configuration
        self.hw_version = hw_version


