class SCRadio(ABC):
    """Small Cell radio"""

    @abstractmethod
    def __init__(self, sc_radio_connection_details: SCRadioConnectionDetails) -> None:
        self.sc_radio_connection_details = sc_radio_connection_details


class RUExtension(object):
    def __init__(
        self,
        radio_type=None,  # type: Optional[str]
        serial_number=None,  # type: Optional[str]
        product_code=None,  # type: Optional[str]
    ):
        """

        :param Optional[str] radio_type: str type (unique identifier) of the radio module, should be one of RadioTypes' attributes
        :param Optional[str] serial_number: serial number of RU Extension
        :param Optional[str] product_code: product code of RU Extension
        """
        self.radio_type = radio_type
        self.serial_number = serial_number
        self.product_code = product_code


class SC5GRadio(RU, SCRadio):
    def __init__(
        self,
        ru_hw_group,  # type: str
        sc_radio_connection_details,  # type: SCRadioConnectionDetails
        lmp_connection,  # type: SshServiceDetails
        pdu_port,  # type: PduPort
        radio_type=None,  # type: Optional[str]
        positioner=None,  # type: Optional[RadioHeadPositioner]
        serial_number=None,  # type: Optional[str]
    ):
        """

        :param str ru_hw_group: Radio Unit hardware group
        :param SCRadioConnectionDetails sc_radio_connection_details: SCRadioConnectionDetails class instance object
        :param SshServiceDetails lmp_connection: SshServiceDetails class instance object
        :param PduPort pdu_port: PduPort class instance object
        :param Optional[str] radio_type: str type (unique identifier) of the radio module, should be one of SCRadioTypes' attributes
        :param Optional[RadioHeadPositioner] positioner: RadioHeadPositioner reference or None if no positioner
        :param Optional[str] serial_number: serial number of Radio Unit
        """
        SCRadio.__init__(self, sc_radio_connection_details=sc_radio_connection_details)
        RU.__init__(
            self,
            ru_hw_group=ru_hw_group,
            default_ssh_connection_details=sc_radio_connection_details.ssh,
            lmp_connection=lmp_connection,
            pdu_port=pdu_port,
            radio_type=radio_type,
            positioner=positioner,
            serial_number=serial_number,
        )


# TODO: delete class RadioModule with next major release
class RadioModule(RUExtension):
    def __init__(
        self,
        default_ssh_connection_details,
        pdu_port=None,
        radio_type=None,
        serial_number=None,
    ):
        # type: (SshServiceDetails, Optional[PduPort], Optional[str], Optional[str]) -> None
        """

        :param SshServiceDetails default_ssh_connection_details: SshServiceDetails class instance object
        :param Optional[PduPort] pdu_port: pdu port of enb
        :param Optional[str] radio_type: str type (unique identifier) of the radio module, should be one of RadioTypes' attributes
        :param Optional[str] serial_number: serial number of RU Extension
        """

        RUExtension.__init__(self, radio_type=radio_type, serial_number=serial_number)

        logger.warning(
            "This class is deprecated and should not be used. Use RU class instead."
        )
        self.default_ssh_connection_details = default_ssh_connection_details
        self.pdu_port = pdu_port


class SC4GRadio(RadioModule, SCRadio):
    def __init__(
        self, sc_radio_connection_details, radio_type=None, serial_number=None
    ):
        # type: (SCRadioConnectionDetails, Optional[str], Optional[str]) -> None
        """

        :param SCRadioConnectionDetails sc_radio_connection_details: SCRadioConnectionDetails class instance object
        :param Optional[str] radio_type: str type (unique identifier) of the radio module, should be one of RadioTypes' attributes
        :param Optional[str] serial_number: serial number of RadioModule
        """
        SCRadio.__init__(self, sc_radio_connection_details=sc_radio_connection_details)
        RadioModule.__init__(
            self,
            default_ssh_connection_details=sc_radio_connection_details.ssh,
            radio_type=radio_type,
            serial_number=serial_number,
        )


class RadioHeadPositioner(object):

    @abstractmethod
    def __init__(self, *args, **kwargs):
        pass

    def __taf_contract_radioheadpositioner__(self):
        positioner_type = self.__class__.__name__
        if positioner_type == RadioHeadPositioner.__name__:
            raise ValueError(
                "Invalid contract provider: RadioHeadPositioner is an abstract class. "
                "The actual instance should be of its subclass."
            )
        return {"type": positioner_type}


